entries[1278772] = { ["name"] = "Malevolent Boons", ["text"] = "The enemies in the site are using dark obelisks to empower their forces. Disable these or face them with their malevolent boons.\n\nIncreases Spoils by 20% when selected.\n\n[Unlock: Complete a Tier 2 Ritual Site then speak with Lady Darkglen in Silvermoon City. The tier required reduces each week. ]" }
